"use strict";(self.webpackChunkwhimsylabs_website=self.webpackChunkwhimsylabs_website||[]).push([[1235],{1235(e,s,r){r.d(s,{content:()=>l,description:()=>t,keywords:()=>a,title:()=>n});r(5043);var i=r(579);const n="Triple Science pour tous d'ici 2028 : assurer les travaux pratiques",t="Un droit \xe0 la Triple Science (les trois sciences distinctes au GCSE) arrive pour septembre 2028, mais les travaux pratiques ont presque diminu\xe9 de moiti\xe9 depuis 2016. Voici comment les laboratoires virtuels aident les \xe9coles \xe0 le mettre en \u0153uvre.",a=["droit \xe0 la Triple Science 2028","Curriculum and Assessment Review","revue Francis sciences","d\xe9clin des sciences pratiques","p\xe9nurie d'enseignants de physique","laboratoires de sciences virtuels \xe9coles","sciences distinctes GCSE","laboratoires virtuels Chromebook"],l=(0,i.jsxs)(i.Fragment,{children:[(0,i.jsxs)("p",{children:["Lorsque la Curriculum and Assessment Review (revue du programme et de l'\xe9valuation) a publi\xe9 son rapport final en novembre 2025, une recommandation scientifique s'est d\xe9marqu\xe9e : un droit statutaire pour tout \xe9l\xe8ve souhaitant \xe9tudier les sciences distinctes, biologie, chimie et physique, sous forme de trois GCSE (examen de fin de scolarit\xe9 obligatoire). Le gouvernement l'a accept\xe9, s'engageant \xe0 aider les \xe9coles \xe0 construire une offre de Triple Science (les trois sciences distinctes) avant d'instaurer ce droit, avec un programme national r\xe9vis\xe9 attendu au printemps 2027 et un premier enseignement \xe0 partir de septembre 2028 (",(0,i.jsx)("a",{href:"https://www.gov.uk/government/news/new-curriculum-to-give-young-people-the-skills-for-life-and-work",target:"_blank",rel:"noopener noreferrer",children:"DfE, 2025"}),")."]}),(0,i.jsx)("p",{children:"L'ambition est juste. L'acc\xe8s \xe0 la Triple Science a longtemps \xe9t\xe9 in\xe9gal, et les sciences distinctes ouvrent la voie \xe0 des \xe9tudes et des carri\xe8res STEM (sciences, technologies, ing\xe9nierie et math\xe9matiques) ult\xe9rieures. Mais un probl\xe8me difficile se cache sous cette politique. Ce droit promet plus de sciences \xe0 davantage d'\xe9l\xe8ves au moment pr\xe9cis o\xf9 les travaux pratiques, la partie de la science qui en fait une science, disparaissent discr\xe8tement des salles de classe. On demande aux \xe9coles d'\xe9largir l'acc\xe8s aux sciences pratiques alors que la base pratique s'\xe9rode, et aucune \xe9cole ne peut combler cet \xe9cart par la construction d'ici 2028."}),(0,i.jsx)("h2",{children:"Qu'exige r\xe9ellement le droit \xe0 la Triple Science ?"}),(0,i.jsxs)("p",{children:["La revue, dirig\xe9e par la professeure Becky Francis (pr\xe9sidente de la revue du programme), a explicitement pr\xe9sent\xe9 ce droit comme un moyen de lever les obstacles socio-\xe9conomiques aux STEM, car l'acc\xe8s aux sciences distinctes varie depuis longtemps selon le code postal et selon la capacit\xe9 d'une \xe9cole \xe0 les doter en personnel et en ressources. Les \xe9l\xe8ves d\xe9favoris\xe9s restent environ deux fois moins susceptibles de suivre les sciences distinctes que leurs camarades plus ais\xe9s. Le gouvernement s'est engag\xe9 sur ce droit mais, comme l'ont not\xe9 des commentateurs, n'a pas encore expos\xe9 comment il aidera les \xe9coles \xe0 le mettre en \u0153uvre (",(0,i.jsx)("a",{href:"https://schoolsweek.co.uk/new-curriculum-to-be-introduced-in-2028-as-review-published/",target:"_blank",rel:"noopener noreferrer",children:"Schools Week, 2025"}),")."]}),(0,i.jsx)("p",{children:"L'implication pratique est importante. Pour la plupart des \xe9coles, offrir la Triple Science \xe0 chaque \xe9l\xe8ve qui le souhaite signifie davantage de temps de programme et de travail en laboratoire par cohorte, car trois GCSE comportent plus de contenu et plus de travaux pratiques obligatoires que la science combin\xe9e. Ce droit n'est pas seulement une question d'emploi du temps. C'est la question de savoir si une \xe9cole dispose de la capacit\xe9 de laboratoire n\xe9cessaire pour faire passer plus d'\xe9l\xe8ves par plus d'exp\xe9riences."}),(0,i.jsx)("h2",{children:"Pourquoi ce droit est-il si difficile \xe0 mettre en \u0153uvre ?"}),(0,i.jsxs)("p",{children:["Trois contraintes incontournables se dressent sur le chemin, et la revue elle-m\xeame les a reconnues : la pression sur les emplois du temps, la capacit\xe9 des laboratoires et une p\xe9nurie d'enseignants sp\xe9cialis\xe9s, en particulier en physique. La crainte que le plan ne risque de devancer le corps enseignant de physique a \xe9t\xe9 soulev\xe9e d\xe8s la publication (",(0,i.jsx)("a",{href:"https://www.tes.com/magazine/news/secondary/curriculum-review-triple-science-teacher-shortages",target:"_blank",rel:"noopener noreferrer",children:"Tes, 2025"}),"). Les \xe9coles les moins en mesure d'offrir la Triple Science aujourd'hui sont g\xe9n\xe9ralement celles qui desservent des communaut\xe9s d\xe9favoris\xe9es, qui disposent souvent du moins de laboratoires, du moins de temps de technicien et du recrutement le plus difficile. Un droit sur le papier ne cr\xe9e pas un laboratoire libre ni un sp\xe9cialiste de la physique."]}),(0,i.jsx)("h2",{children:"Le d\xe9clin silencieux des travaux pratiques"}),(0,i.jsxs)("p",{children:["La tendance \xe0 laquelle ce droit s'oppose est bien document\xe9e. Le Science Education Tracker de la Royal Society et d'EngineeringUK a constat\xe9 que la proportion d'\xe9l\xe8ves de GCSE r\xe9alisant des travaux pratiques au moins une fois toutes les deux semaines est pass\xe9e de 44% en 2016 \xe0 26% en 2023, les d\xe9monstrations vid\xe9o rempla\xe7ant de plus en plus les exp\xe9riences que les \xe9l\xe8ves r\xe9alisaient autrefois eux-m\xeames (",(0,i.jsx)("a",{href:"https://royalsociety.org/news/2024/04/science-education-tracker-2023/",target:"_blank",rel:"noopener noreferrer",children:"Royal Society, 2024"}),")."]}),(0,i.jsx)("p",{children:"Dans le m\xeame temps, 71% des \xe9l\xe8ves d\xe9clarent vouloir faire davantage de sciences pratiques, et pour les plus jeunes, la possibilit\xe9 de r\xe9aliser des exp\xe9riences figure parmi les raisons les plus fortes qu'ils invoquent pour vouloir continuer \xe0 \xe9tudier les sciences. La demande est l\xe0. L'acc\xe8s ne l'est pas. \xc9largir un droit alors que la base pratique se r\xe9duit risque de creuser l'\xe9cart m\xeame qu'il est cens\xe9 combler, \xe0 moins que les \xe9coles ne puissent ajouter une capacit\xe9 pratique qui ne d\xe9pende pas de la construction de nouvelles salles et de l'embauche de personnel suppl\xe9mentaire."}),(0,i.jsx)("h2",{children:"Pourquoi on ne peut pas s'en sortir par la construction d'ici 2028"}),(0,i.jsx)("p",{children:"La r\xe9ponse \xe9vidente, davantage de laboratoires et davantage d'enseignants sp\xe9cialis\xe9s, se heurte au calendrier. Construire et \xe9quiper de nouveaux laboratoires est lent et co\xfbteux, le nombre de techniciens est en baisse, et les enseignants de physique sont en p\xe9nurie chronique. Avec un programme attendu au printemps 2027 et un premier enseignement en septembre 2028, les \xe9coles disposent d'une fen\xeatre \xe9troite, et les programmes d'investissement et les fili\xe8res de recrutement n'\xe9voluent pas \xe0 ce rythme. Les \xe9coles qui attendent de nouveaux laboratoires et de nouveaux personnels arriveront \xe0 2028 dans l'incapacit\xe9 d'honorer ce droit pr\xe9cis\xe9ment pour les \xe9l\xe8ves qu'il \xe9tait cens\xe9 atteindre."}),(0,i.jsx)("h2",{children:"Comment les laboratoires virtuels ajoutent une capacit\xe9 pratique sans nouvelles salles"}),(0,i.jsx)("p",{children:"C'est ici que les laboratoires virtuels changent ce qui est possible. WhimsyLabs ex\xe9cute de v\xe9ritables laboratoires de biologie, de chimie et de physique \xe0 moteur physique dans le navigateur, sur les Chromebooks que les \xe9coles poss\xe8dent d\xe9j\xe0. Chaque \xe9l\xe8ve peut r\xe9aliser l'ensemble des travaux pratiques obligatoires sans attendre un laboratoire libre, un technicien pour pr\xe9parer les r\xe9actifs, ou un sp\xe9cialiste pour superviser une proc\xe9dure dangereuse. Plusieurs classes peuvent mener des travaux pratiques en m\xeame temps, il n'y a pas de consommables \xe0 financer, et il n'y a ni temps d'installation ni temps de nettoyage \xe0 absorber."}),(0,i.jsx)("p",{children:"Pour une \xe9cole qui ne peut pas offrir la Triple Science aujourd'hui faute de capacit\xe9 de laboratoire, c'est la diff\xe9rence entre honorer ce droit et refuser des \xe9l\xe8ves. Et parce que les laboratoires fonctionnent sur des appareils existants, les \xe9coles disposant de la plus faible infrastructure pratique, souvent celles qui desservent des communaut\xe9s d\xe9favoris\xe9es, sont pr\xe9cis\xe9ment celles qui en b\xe9n\xe9ficient le plus. Ce droit a \xe9t\xe9 con\xe7u pour r\xe9duire un \xe9cart d'\xe9quit\xe9, et une voie de mise en \u0153uvre qui ne d\xe9pend pas du parc de laboratoires existant d'une \xe9cole est ce qui rend cet objectif r\xe9aliste plut\xf4t qu'aspirationnel."}),(0,i.jsx)("h2",{children:"Mais le travail pratique virtuel est-il \xab\xa0r\xe9el\xa0\xbb ?"}),(0,i.jsx)("p",{children:"C'est une objection l\xe9gitime, et elle m\xe9rite une r\xe9ponse directe. Ce qui remplace actuellement les travaux pratiques dans de nombreuses salles de classe, c'est la d\xe9monstration vid\xe9o, o\xf9 les \xe9l\xe8ves regardent quelqu'un d'autre r\xe9aliser l'exp\xe9rience. Un laboratoire virtuel est l'oppos\xe9 du fait de regarder. L'\xe9l\xe8ve ex\xe9cute la proc\xe9dure, prend les d\xe9cisions, se trompe, et recommence. Notre \xe9valuation bas\xe9e sur les processus consigne chaque action qu'un \xe9l\xe8ve effectue et note sa technique, de sorte qu'un enseignant peut constater qu'un \xe9l\xe8ve a r\xe9ellement r\xe9alis\xe9 le titrage ou la dissection plut\xf4t que de simplement en observer un."}),(0,i.jsx)("p",{children:"Les laboratoires virtuels ne sont pas un argument contre le travail \xe0 la paillasse chaque fois qu'une \xe9cole peut le proposer. Ils constituent une bien meilleure r\xe9ponse \xe0 un d\xe9ficit de capacit\xe9 qu'une vid\xe9o de d\xe9monstration, et ils permettent \xe0 une \xe9cole de dispenser des sciences pratiques au niveau du droit \xe0 chaque \xe9l\xe8ve plut\xf4t qu'aux seuls \xe9l\xe8ves qui fr\xe9quentent un d\xe9partement bien \xe9quip\xe9."}),(0,i.jsx)("h2",{children:"Ce que les responsables d'\xe9coles et de trusts peuvent faire avant 2028"}),(0,i.jsx)("p",{children:"Le d\xe9lai est court, mais il est r\xe9el. Les responsables peuvent commencer d\xe8s maintenant en recensant l'offre actuelle de Triple Science et en identifiant les cohortes et les sciences qu'ils ne peuvent pas proposer aujourd'hui. L'\xe9tape suivante consiste \xe0 cartographier o\xf9 se situe r\xe9ellement la contrainte incontournable, qu'il s'agisse de la capacit\xe9 de laboratoire, du temps de technicien, de la dotation en personnel sp\xe9cialis\xe9 ou de l'espace dans l'emploi du temps, car la bonne r\xe9ponse diff\xe8re dans chaque cas. \xc0 partir de l\xe0, un projet pilote cibl\xe9 peut utiliser des laboratoires virtuels pour accro\xeetre la capacit\xe9 pratique pour les manques pr\xe9cis, en donnant la priorit\xe9 aux cohortes d\xe9favoris\xe9es que ce droit est cens\xe9 atteindre."}),(0,i.jsx)("p",{children:"Le droit \xe0 la Triple Science est une v\xe9ritable occasion d'\xe9largir l'acc\xe8s aux sciences distinctes, mais seulement pour les \xe9coles qui disposent d'un moyen de dispenser des sciences pratiques \xe0 grande \xe9chelle. Les \xe9coles qui planifient d\xe8s maintenant leur voie de mise en \u0153uvre, plut\xf4t que d'attendre des b\xe2timents et du personnel qui n'arriveront pas \xe0 temps, seront celles qui seront pr\xeates lorsque le premier enseignement commencera en 2028."}),(0,i.jsxs)(i.Fragment,{children:[(0,i.jsx)("h2",{children:"Articles connexes"}),(0,i.jsxs)("ul",{children:[(0,i.jsx)("li",{children:(0,i.jsx)("a",{href:"/blog/send-white-paper-2026-science-practicals",children:"Le Livre blanc SEND 2026 et l'enseignement des sciences"})}),(0,i.jsx)("li",{children:(0,i.jsx)("a",{href:"/blog/virtual-labs-solve-stem-teacher-shortage-crisis",children:"Comment les laboratoires virtuels aident \xe0 r\xe9soudre la crise de p\xe9nurie d'enseignants STEM"})}),(0,i.jsx)("li",{children:(0,i.jsx)("a",{href:"/blog/virtual-labs-vs-physical-labs-cost-benefit-analysis",children:"Laboratoires virtuels contre laboratoires physiques : une analyse co\xfbts-avantages"})}),(0,i.jsx)("li",{children:(0,i.jsx)("a",{href:"/blog/how-to-choose-virtual-lab-software-school",children:"Comment choisir un logiciel de laboratoire virtuel pour votre \xe9cole"})})]})]}),(0,i.jsxs)("div",{className:"references-section",children:[(0,i.jsx)("h3",{children:"R\xe9f\xe9rences"}),(0,i.jsxs)("ul",{className:"references-list",children:[(0,i.jsxs)("li",{children:["Department for Education. (2025). New curriculum to give young people the skills for life and work. GOV.UK."," ",(0,i.jsx)("a",{href:"https://www.gov.uk/government/news/new-curriculum-to-give-young-people-the-skills-for-life-and-work",target:"_blank",rel:"noopener noreferrer",children:"https://www.gov.uk/government/news/new-curriculum-to-give-young-people-the-skills-for-life-and-work"})]},"ref-1"),(0,i.jsxs)("li",{children:["Department for Education. (2025). Government response to the Curriculum and Assessment Review."," ",(0,i.jsx)("a",{href:"https://assets.publishing.service.gov.uk/media/690b2a4a14b040dfe82922ea/Government_response_to_the_Curriculum_and_Assessment_Review.pdf",target:"_blank",rel:"noopener noreferrer",children:"https://assets.publishing.service.gov.uk/media/690b2a4a14b040dfe82922ea/Government_response_to_the_Curriculum_and_Assessment_Review.pdf"})]},"ref-2"),(0,i.jsxs)("li",{children:["Royal Society & EngineeringUK. (2024). Science Education Tracker 2023."," ",(0,i.jsx)("a",{href:"https://royalsociety.org/news/2024/04/science-education-tracker-2023/",target:"_blank",rel:"noopener noreferrer",children:"https://royalsociety.org/news/2024/04/science-education-tracker-2023/"})]},"ref-3"),(0,i.jsxs)("li",{children:["Tes. (2025). Triple science GCSE plan 'ignores chronic teacher shortages'."," ",(0,i.jsx)("a",{href:"https://www.tes.com/magazine/news/secondary/curriculum-review-triple-science-teacher-shortages",target:"_blank",rel:"noopener noreferrer",children:"https://www.tes.com/magazine/news/secondary/curriculum-review-triple-science-teacher-shortages"})]},"ref-4")]})]})]})}}]);
